def cache_key(self) -> DependencyCacheKey:
    scopes = self.security_scopes
    if scopes is None:
        return (self.call, (), self.computed_scope or "")

    # Only include scopes in the cache key if this dependency or a sub-dependency
    # declares scopes or accesses SecurityScopes.
