        return (self.call, (), self.computed_scope or "")

    return (
        self.call,
        tuple(sorted(set(scopes))),
        self.computed_scope or "",
    )

@cached_property
def _uses_scopes(self) -> bool:
    if self.security_scopes is None:
        return False

    # Check if the dependency itself declares scopes
    if self.security_scopes:
        return True

    # Check sub-dependencies
    for sub_dependant in self.sub_dependants:
        if sub_dependant._uses_scopes:
            return True
    return False

